#include <vector>
#include <algorithm>

class Solution {
public:
    int kthSmallest(std::vector<std::vector<int>>& mat, int k) {
        std::vector<int> cur = {0};
        for (const auto& row : mat) {
            std::vector<int> nextSums;
            for (int x : cur) {
                for (int y : row) {
                    nextSums.push_back(x + y);
                }
            }
            std::sort(nextSums.begin(), nextSums.end());
            if ((int)nextSums.size() > k) nextSums.resize(k);
            cur = nextSums;
        }
        return cur[k - 1];
    }
};

import java.util.*;

class Solution {
    public int kthSmallest(int[][] mat, int k) {
        List<Integer> cur = new ArrayList<>();
        cur.add(0);
        for (int[] row : mat) {
            List<Integer> nextSums = new ArrayList<>();
            for (int x : cur) {
                for (int y : row) {
                    nextSums.add(x + y);
                }
            }
            Collections.sort(nextSums);
            cur = nextSums.subList(0, Math.min(nextSums.size(), k));
        }
        return cur.get(k - 1);
    }
}

var kthSmallest = function(mat, k) {
    let cur = [0];
    for (const row of mat) {
        const nextSums = [];
        for (const x of cur) {
            for (const y of row) {
                nextSums.push(x + y);
            }
        }
        nextSums.sort((a, b) => a - b);
        cur = nextSums.slice(0, k);
    }
    return cur[k - 1];
};
